	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79216), '''String: "Withdrawal tutorial detailed instructions and warnings"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79208), '''String: "\n\nWithdrawal fees are subject to change depending on network conditions. If fees change rapidly after you make a withdrawal request, we may contact you about your withdrawal options.\n\nWithdrawal fees include blockchain transfer fees and are outside our control. The minimum withdrawal amount is typically 2x the transaction fee.\n\nFor supported low-fee networks such as the Bitcoin Lightning Network, transaction fees and minimum withdrawal amounts are usually much lower than on-chain networks.\n\nPlease ensure that the wallet or exchange you are using supports %networkNames% transactions and that you are withdrawing on the correct network. You may permanently lose your assets if you send funds to an incompatible address or to a wallet that you do not control."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79200), '''String: "chosen networks"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79192), '''String: "Withdrawal tutorial note about alternative wallets"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79184), '''String: ", but you can withdraw to any wallet or exchange supporting %networkNames% transactions.\n\n"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79176), '''String: "Withdrawal tutorial intro for single network"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 79168), '''String: "Withdrawal requests can be made to any wallet or exchange supporting %networkNames%. For convenience, here is a wallet our users commonly use:\n"''', True)
